+  nativeReviewFixtureBrokers,
+  withBrokeredNativeDeliveryInvocation,
+  withNativeReviewFixtureHostIdentity,
+} from './native-review-fixture.js';
+
+const root = mkdtempSync(join(tmpdir(), 'delivery-native-attestation-'));
+const storyId = 'B-delivery-native';
+
+function git(...args: string[]): void {
+  execFileSync('git', args, { cwd: root, stdio: 'ignore' });
+}
+
+try {
+  git('init');
+  git('config', 'user.name', 'Smoke');
+  git('config', 'user.email', 'smoke@example.test');
+  writeFileSync(join(root, 'README.md'), 'delivery native authority smoke\n');
+  writeFileSync(join(root, 'lattice.config.json'), `${JSON.stringify({
+    nativeReviewInvocation: { brokers: nativeReviewFixtureBrokers() },
+  }, null, 2)}\n`);
+  git('add', 'README.md', 'lattice.config.json');
+  git('commit', '-m', 'init');
+
+  const store = new StoryStore(root);
+  const now = new Date().toISOString();
+  store.writeStory(storyId, {
+    storyId,
+    name: 'delivery-native',
+    title: 'Delivery native authority',
+    description: 'Broker authority smoke.',
+    type: 'chore',
+    priority: 'medium',
+    phase: 'TEST',
+    createdAt: now,
+    startedAt: now,
+    endedAt: null,
+    events: [],
+  });
+  store.writeChecklist(storyId, { items: [] });
+  const ctx = { root, scanRoot: join(root, 'packages/main'), store };
+  withNativeReviewFixtureHostIdentity({
+    agent: 'lattice-review-delivery',
+    invoke: () => createStoryDispatchHandlers(ctx).dispatch({
+      storyId,
+      agentType: 'lattice-review-delivery',
+    }),
+  });
+
+  const previous = {
+    agent: process.env.LATTICE_AGENT,
+    sessionId: process.env.LATTICE_SESSION_ID,
+    provider: process.env.LATTICE_OWNER_SESSION_ADAPTER_PROVIDER,
+    task: process.env.LATTICE_OWNER_SESSION_ADAPTER_TASK,
+    adapterAgent: process.env.LATTICE_OWNER_SESSION_ADAPTER_AGENT,
+  };
+  try {
+    process.env.LATTICE_AGENT = 'lattice-review-delivery';
+    process.env.LATTICE_SESSION_ID = 'raw-delivery-reviewer-session';
+    process.env.LATTICE_OWNER_SESSION_ADAPTER_PROVIDER = 'codex';
+    process.env.LATTICE_OWNER_SESSION_ADAPTER_TASK = 'raw-delivery-reviewer-task';
+    process.env.LATTICE_OWNER_SESSION_ADAPTER_AGENT = 'lattice-review-delivery';
+    resetSessionIdForTest();
+
+    const handlers = createDeliveryCheckHandlers(ctx);
+    assert.throws(
+      () => handlers.delivery_check_set({
+        storyId,
+        agentId: 'lattice-review-delivery',
+        docsPromises: [],
+        realMachineTests: [],
