    knownDecisionFiles: knownDecisionFilesForReadDiagnostics(ctx, requirementsDir),
    requirementsDir,
  });
  return { readManifest, readLog, readDiagnostics };
}

function formatReadDiagnostics(diagnostics: readonly ReviewerReadDiagnostic[]): string {
